{
  "overview": "Rapid exam revision sheet for Fitts's Law, Hick's Law, and Cognitive Load in Responsive Mobile Interfaces (UI/UX & Product Design), focusing on Quantitative Ergonomics & Interaction Cost.",
  "formulaBank": [
    {
      "name": "Quantitative Ergonomics & Interaction Cost",
      "formula": "MT = a + b \\log_2\\left(\\frac{2D}{W}\\right)",
      "variables": "Milliseconds (ms) or seconds (s) for movement/reaction time; bits for Index of Difficulty",
      "whenToUse": "Apply when analyzing Fitts's Law, Hick's Law, and Cognitive Load in Responsive Mobile Interfaces problems in UI/UX & Product Design."
    }
  ],
  "keyDefinitions": [
    {
      "term": "Quantitative Ergonomics & Interaction Cost",
      "definition": "Fitts's Law models the time required to rapidly move a pointer or thumb to a target area as a logarithmic function of the ratio between the distance to the target (D) and the width of the target (W)."
    }
  ],
  "workedDerivations": [
    {
      "title": "Derivation & Application of Quantitative Ergonomics & Interaction Cost",
      "steps": "1. Define Index of Difficulty ID = \\log_2(2D/W) measured in bits.\n2. Movement Time MT scales linearly with ID: MT = a + b \\cdot ID.\n3. On mobile touchscreens, placing primary actions in the natural thumb zone minimizes D while enforcing a minimum 44x44px hit target maximizes W.\n\nWorked Example: Moving a mobile checkout button from the top-right corner (D = 480px, W = 32px, ID = 4.91 bits) to a full-width sticky bottom bar (D = 120px, W = 320px, ID = 0.81 bits) reduces movement difficulty by over 80%."
    }
  ],
  "examTraps": [
    "Applying Hick's Law blindly by hiding all navigation items inside deep nested hamburger menus increases interaction cost (tap count and working memory load) rather than simplifying decision-making."
  ]
}

