  "formulaBank": [
    {
      "name": "Multi-Version Concurrency Control & Snapshot Isolation",
      "formula": "T_{\\text{commit}} \\implies \\text{LSN}_{\\text{disk}} \\ge \\text{LSN}_{\\text{tx}}",
      "variables": "Transactions per second (TPS) and Log Sequence Numbers (LSN)",
      "whenToUse": "Apply when analyzing ACID Transactions, Write-Ahead Logging (WAL), and MVCC Concurrency Control problems in Database Systems."
    }
  ],
  "keyDefinitions": [
    {
      "term": "Multi-Version Concurrency Control & Snapshot Isolation",
      "definition": "MVCC allows concurrent readers and writers to operate without blocking each other by maintaining multiple timestamped versions of each tuple."
    }
  ],
  "workedDerivations": [
    {
      "title": "Derivation & Application of Multi-Version Concurrency Control & Snapshot Isolation",
      "steps": "1. When transaction T updates a row, the database writes a new version tagged with tx_id = T rather than overwriting in place.\n2. Concurrent readers inspect the latest version committed prior to their snapshot timestamp.\n3. Before acknowledging COMMIT, the WAL protocol flushes the redo log record to non-volatile storage.\n\nWorked Example: User A starts a report query at t=10. At t=12, User B updates a balance from $100 to $250 and commits. User A's query continues reading the t=10 version ($100), guaranteeing repeatable reads."
    }
  ],
  "examTraps": [
    "Assuming Snapshot Isolation prevents all serialization anomalies—write skew can still occur when two concurrent transactions read overlapping data and write to disjoint rows."
  ]
}

