{
  "overview": "Rapid exam revision sheet for Virtual Memory, Page Tables, TLB Reach, and Page Fault Handling (Operating Systems), focusing on Hardware-Assisted Virtual-to-Physical Address Translation.",
  "formulaBank": [
    {
      "name": "Hardware-Assisted Virtual-to-Physical Address Translation",
      "formula": "\\text{EAT} = \\alpha(\\epsilon + t_m) + (1 - \\alpha)(\\epsilon + 2t_m)",
      "variables": "Nanoseconds (ns) for Effective Access Time (EAT); Hit Ratio \\alpha in [0, 1]",
      "whenToUse": "Apply when analyzing Virtual Memory, Page Tables, TLB Reach, and Page Fault Handling problems in Operating Systems."
    }
  ],
  "keyDefinitions": [
    {
      "term": "Hardware-Assisted Virtual-to-Physical Address Translation",
      "definition": "Virtual memory abstracts physical RAM into a contiguous private address space for each process using hardware page tables and a Translation Lookaside Buffer (TLB) cache."
    }
  ],
  "workedDerivations": [
    {
      "title": "Derivation & Application of Hardware-Assisted Virtual-to-Physical Address Translation",
      "steps": "1. Split virtual address into Virtual Page Number (VPN) and page offset.\n2. On a TLB hit (probability \\alpha), physical frame number is retrieved in \\epsilon ns, followed by 1 memory access (t_m).\n3. On a TLB miss (1 - \\alpha) in a single-level page table, hardware walks memory (+t_m) before accessing the data (+t_m).\n\nWorked Example: With TLB lookup \\epsilon = 1\\,\\text{ns}, RAM access t_m = 100\\,\\text{ns}, and TLB hit rate \\alpha = 0.98: EAT = 0.98(101) + 0.02(201) = 98.98 + 4.02 = 103.0\\,\\text{ns}."
    }
  ],
  "examTraps": [
    "Confusing a TLB miss (which merely requires walking the page table in RAM, costing ~100 ns) with a hard page fault (which requires fetching a page from SSD/disk, costing millions of nanoseconds)."
  ]
}

