{
  "overview": "Rapid exam revision sheet for SN1 vs SN2 Nucleophilic Substitution Mechanisms, Stereochemistry, and Solvent Effects (Organic Chemistry), focusing on Bimolecular Concerted Backside Attack vs Unimolecular Carbocation Intermediate.",
  "formulaBank": [
    {
      "name": "Bimolecular Concerted Backside Attack vs Unimolecular Carbocation Intermediate",
      "formula": "r_{\\text{SN2}} = k[\\text{R-LG}][\\text{Nu}^-], \\quad r_{\\text{SN1}} = k[\\text{R-LG}]",
      "variables": "Reaction rate in M\\cdot s^{-1}; rate constant k in M^{-1}s^{-1} (SN2) or s^{-1} (SN1)",
      "whenToUse": "Apply when analyzing SN1 vs SN2 Nucleophilic Substitution Mechanisms, Stereochemistry, and Solvent Effects problems in Organic Chemistry."
    }
  ],
  "keyDefinitions": [
    {
      "term": "Bimolecular Concerted Backside Attack vs Unimolecular Carbocation Intermediate",
      "definition": "SN2 is a concerted, one-step bimolecular substitution resulting in complete Walden inversion of configuration, whereas SN1 is a two-step unimolecular substitution via a planar carbocation intermediate yielding racemization."
    }
  ],
  "workedDerivations": [
    {
      "title": "Derivation & Application of Bimolecular Concerted Backside Attack vs Unimolecular Carbocation Intermediate",
      "steps": "1. In SN2, the nucleophile attacks the \\sigma^* antibonding orbital 180^\\circ opposite the leaving group; steric hindrance on tertiary carbons blocks backside approach.\n2. In SN1, the rate-determining step is heterolytic cleavage of the C-LG bond to form a sp^2 carbocation stabilized by hyperconjugation and inductive effects (3^\\circ > 2^\\circ \\gg 1^\\circ).\n\nWorked Example: Reacting (R)-2-bromobutane with NaCN in DMSO (polar aprotic) proceeds via SN2 to yield pure (S)-2-cyanobutane with 100% inversion of stereochemistry."
    }
  ],
  "examTraps": [
    "Using a polar protic solvent (like water or ethanol) when attempting an SN2 reaction cages the anionic nucleophile in hydrogen bonds, drastically slowing SN2 and favoring SN1/E1 pathways."
  ]
}

