{
  "overview": "Rapid exam revision sheet for Event-Driven Microservices, Outbox Pattern, Idempotency Keys, and Saga Orchestration (Software Architecture), focusing on Distributed Eventual Consistency without Two-Phase Commit (2PC).",
  "formulaBank": [
    {
      "name": "Distributed Eventual Consistency without Two-Phase Commit (2PC)",
      "formula": "P(\\text{at-least-once}) + \\text{Idempotent}(f(x)) \\implies \\text{Effectively-Once}",
      "variables": "End-to-end p99 latency (ms) and message throughput (events/sec)",
      "whenToUse": "Apply when analyzing Event-Driven Microservices, Outbox Pattern, Idempotency Keys, and Saga Orchestration problems in Software Architecture."
    }
  ],
  "keyDefinitions": [
    {
      "term": "Distributed Eventual Consistency without Two-Phase Commit (2PC)",
      "definition": "The Transactional Outbox Pattern guarantees atomic database state updates and message broker publication by writing outgoing domain events into a local database outbox table within the same ACID transaction."
    }
  ],
  "workedDerivations": [
    {
      "title": "Derivation & Application of Distributed Eventual Consistency without Two-Phase Commit (2PC)",
      "steps": "1. Dual-writing directly to a database and Kafka risks partial failure if the process crashes between the two network calls.\n2. Inserting the business row and the outbox event row in one local SQL transaction guarantees atomicity.\n3. An asynchronous relay polls or tails the transaction log (CDC) and publishes to the broker with at-least-once delivery; consumers enforce idempotency via unique event_id keys.\n\nWorked Example: When OrderService creates Order #901, it inserts Order #901 and OutboxEvent(id='evt_901', type='OrderCreated') in one COMMIT. PaymentService records 'evt_901' in processed_events before charging the card."
    }
  ],
  "examTraps": [
    "Publishing an event to Kafka/RabbitMQ inside a database transaction before COMMIT can cause downstream services to process phantom events if the local database transaction subsequently rolls back."
  ]
}

