{
  "cards": [
    {
      "front": "Define Quantitative Ergonomics & Interaction Cost in the context of Fitts's Law, Hick's Law, and Cognitive Load in Responsive Mobile Interfaces.",
      "back": "Fitts's Law models the time required to rapidly move a pointer or thumb to a target area as a logarithmic function of the ratio between the distance to the target (D) and the width of the target (W).",
      "hint": "Think about the analogy: Fitts's Law is like tossing a crumpled paper into a trash can: a wide bin right next to yo..."
    },
    {
      "front": "State the primary governing equation/complexity for Quantitative Ergonomics & Interaction Cost and its units.",
      "back": "$$MT = a + b \\log_2\\left(\\frac{2D}{W}\\right)$$ — Units/Scale: Milliseconds (ms) or seconds (s) for movement/reaction time; bits for Index of Difficulty.",
      "hint": "Inline relationship: $RT = a + b \\log_2(n)$"
    },
    {
      "front": "What is the #1 exam misconception or pitfall regarding Fitts's Law, Hick's Law, and Cognitive Load in Responsive Mobile Interfaces?",
      "back": "Applying Hick's Law blindly by hiding all navigation items inside deep nested hamburger menus increases interaction cost (tap count and working memory load) rather than simplifying decision-making.",
      "hint": "Carefully check conventions and boundary assumptions."
    },
    {
      "front": "Walk through the key derivation steps for Quantitative Ergonomics & Interaction Cost.",
      "back": "1. Define Index of Difficulty ID = \\log_2(2D/W) measured in bits.\n2. Movement Time MT scales linearly with ID: MT = a + b \\cdot ID.\n3. On mobile touchscreens, placing primary actions in the natural thumb zone minimizes D while enforcing a minimum 44x44px hit target maximizes W.",
      "hint": "Break it down into 3 logical steps."
    }
  ]
}

