{
  "cards": [
    {
      "front": "Define Multi-Version Concurrency Control & Snapshot Isolation in the context of ACID Transactions, Write-Ahead Logging (WAL), and MVCC Concurrency Control.",
      "back": "MVCC allows concurrent readers and writers to operate without blocking each other by maintaining multiple timestamped versions of each tuple.",
      "hint": "Think about the analogy: MVCC is like Google Docs version history: while an editor is typing a new draft, readers c..."
    },
    {
      "front": "State the primary governing equation/complexity for Multi-Version Concurrency Control & Snapshot Isolation and its units.",
      "back": "$$T_{\\text{commit}} \\implies \\text{LSN}_{\\text{disk}} \\ge \\text{LSN}_{\\text{tx}}$$ — Units/Scale: Transactions per second (TPS) and Log Sequence Numbers (LSN).",
      "hint": "Inline relationship: $\\text{ReadView}(T_i) = \\{v \\mid \\text{tx}_{\\text{min}} \\le v < \\text{tx}_{\\text{max}}\\}$"
    },
    {
      "front": "What is the #1 exam misconception or pitfall regarding ACID Transactions, Write-Ahead Logging (WAL), and MVCC Concurrency Control?",
      "back": "Assuming Snapshot Isolation prevents all serialization anomalies—write skew can still occur when two concurrent transactions read overlapping data and write to disjoint rows.",
      "hint": "Carefully check conventions and boundary assumptions."
    },
    {
      "front": "Walk through the key derivation steps for Multi-Version Concurrency Control & Snapshot Isolation.",
      "back": "1. When transaction T updates a row, the database writes a new version tagged with tx_id = T rather than overwriting in place.\n2. Concurrent readers inspect the latest version committed prior to their snapshot timestamp.\n3. Before acknowledging COMMIT, the WAL protocol flushes the redo log record to non-volatile storage.",
      "hint": "Break it down into 3 logical steps."
    }
  ]
}

