{
  "cards": [
    {
      "front": "Define Steady-State Enzyme-Substrate Reaction Rate in the context of Michaelis-Menten Enzyme Kinetics, Lineweaver-Burk Plots, and Competitive Inhibition.",
      "back": "The Michaelis-Menten equation relates the initial reaction velocity v_0 of an enzyme-catalyzed reaction to the substrate concentration [S], maximum velocity V_max, and Michaelis constant K_m.",
      "hint": "Think about the analogy: Enzyme saturation is like toll booths on a highway: when traffic ([S]) is light, cars pass..."
    },
    {
      "front": "State the primary governing equation/complexity for Steady-State Enzyme-Substrate Reaction Rate and its units.",
      "back": "$$v_0 = \\frac{V_{\\max}[S]}{K_m + [S]}$$ — Units/Scale: Reaction velocity v_0 in \\mu\\text{M/s}; substrate concentration [S] and K_m in \\text{mM} or \\mu\\text{M}.",
      "hint": "Inline relationship: $K_m = \\frac{k_{-1} + k_2}{k_1}$"
    },
    {
      "front": "What is the #1 exam misconception or pitfall regarding Michaelis-Menten Enzyme Kinetics, Lineweaver-Burk Plots, and Competitive Inhibition?",
      "back": "Students often think a competitive inhibitor lowers V_max; in reality, competitive inhibition increases apparent K_m while V_max remains unchanged because high substrate concentrations outcompete the inhibitor.",
      "hint": "Carefully check conventions and boundary assumptions."
    },
    {
      "front": "Walk through the key derivation steps for Steady-State Enzyme-Substrate Reaction Rate.",
      "back": "1. Assume E + S <-> ES -> E + P with steady-state d[ES]/dt = 0.\n2. Rate of formation k_1[E][S] equals rate of breakdown (k_{-1} + k_2)[ES].\n3. Substituting [E]_T = [E] + [ES] and v_0 = k_2[ES] yields v_0 = V_max[S] / (K_m + [S]).",
      "hint": "Break it down into 3 logical steps."
    }
  ]
}

